// Regex check
const isValid = /^0x[a-fA-F0-9]{40}$/.test(addr);

return {
  caseId: input.caseId,
  party: input.party, 
  wallet: isValid ? addr.toLowerCase() : addr,
  isValid: isValid, // Pass this to an IF node
};

