parameters.jsCode:
// ==============================
// 1. Load Case Data
// ==============================
const caseRow = $('Lookup Case').first().json;

const caseId = caseRow['Case ID'];
const deposited = Number(caseRow['Deposited Fund'] || 0);
const escrowWei = Number(caseRow['Escrow Fund'] || 0);
const feeWei = Number(caseRow['Fee'] || 0);

const escrowEth = (escrowWei / 1e18);
const feeEth = (feeWei / 1e18);
const totalRequiredETH = (escrowWei + feeWei)/1e18;
const depositedETH = deposited / 1e18;

// ==============================
// 2. Party & Response Resolution
// ==============================
const signNode = $('Signature Response').first().json;
const currentParty = signNode.query.party;
const currentAction = signNode.query.action;

const sellerResponse =
  caseRow['Seller Response'] ||
  (currentParty === 'Seller' ? currentAction : 'awaiting response');

const buyerResponse =
  caseRow['Buyer Response'] ||
  (currentParty === 'Buyer' ? currentAction : 'awaiting response');

// ==============================
// 3. Build Deposit URL
// ==============================
const baseWebhookUrl = signNode.webhookUrl.replace(/\/[^/]*$/, '');
const depositUrl =
  `${baseWebhookUrl}/deposit?caseId=${encodeURIComponent(caseId)}`;

// ==============================
// 4. Conditional HTML Block
// ==============================
let actionHtml = '';

if (sellerResponse === 'accept' && buyerResponse === 'accept') {
  actionHtml = `
  <div style="margin-top:30px;padding:24px;background:#f8fbff;border:1px solid #d0e3ff;border-radius:10px;">
    <h4 style="margin:0 0 12px 0;color:#0056b3;">
     Legal Effectiveness Notice
    </h4>
    <p style="font-size:14px;color:#33475b;line-height:1.6;">
      Both parties have accepted the contract.
      <br/><br/>
      Buyer must deposit:
      <strong>${escrowEth} ETH</strong> escrow  
      + <strong>${feeEth} ETH</strong> fee.
      <br/><br/>
      Once the full amount is received, the case will become <strong>effective</strong>.
    </p>
    <a href="${depositUrl}"
       style="display:inline-block;margin-top:14px;padding:12px 20px;
              background:#0056b3;color:#fff;text-decoration:none;
              border-radius:6px;font-weight:600;">
      Deposit Ether
    </a>
  </div>`;
}

// ==============================
// 5. Return for Email Node
// ==============================
return {
  baseWebhookUrl,
  caseId,
  sellerResponse,
  buyerResponse,
  depositedETH,
  totalRequiredETH,
  actionHtml
};

